   "solution": "q = int(input())\na = []\nfor _ in range(q):\n    cmd = input().split()\n    if cmd[0] == 'add':\n        a.append(int(cmd[1]))\n    elif cmd[0] == 'front':\n        a.insert(0, int(cmd[1]))\n    elif cmd[0] == 'pop':\n        a.pop()\n    elif cmd[0] == 'remove':\n        x = int(cmd[1])\n        if x in a:\n            a.remove(x)\n    else:\n        print(*a if a else ['empty'])",
