   "solution": "n = int(input())\na = list(map(int, input().split()))\nb = list(map(int, input().split()))\nanswer = 'NO'\nfor k in range(n):\n    if a[n - k:] + a[:n - k] == b:\n        answer = k\n        break\nprint(answer)",
